      {
        "type": "ul",
        "items": [
          "Deine Kraftwerte im Training bleiben stabil oder steigen sogar leicht",
          "Der Taillenumfang sinkt schneller als der Umfang von Armen und Beinen",
          "Alltagsaufgaben wie Treppen oder Einkaufstaschen fallen dir leichter, nicht schwerer",
          "Auf Fotos wirkst du straffer und nicht einfach nur schmaler"
        ]
      },
      {
        "type": "p",
        "text": "Fällt deine Kraft über mehrere Wochen deutlich ab, ist das ein Warnsignal. Dann stimmen meistens Protein, Trainingsvolumen oder Regeneration nicht, und du solltest nachjustieren, bevor die Substanz weg ist."
      },
      {
        "type": "h2",
        "text": "Dein Wochenplan in der Praxis"
      },
      {
        "type": "p",
        "text": "So sieht die Umsetzung bei meinen Klienten konkret aus: Montag und Donnerstag je eine Ganzkörpereinheit, dazwischen an mindestens zwei Tagen 8.000 Schritte oder mehr. Jede Mahlzeit beginnt mit der Proteinquelle, und einmal pro Woche werden Gewicht, Taillenumfang und ein Kraftwert notiert. An Tagen mit Übelkeit wird das Training verkürzt statt gestrichen. Nebenwirkungen, die das Training regelmäßig unmöglich machen, gehören immer ins Gespräch mit deinem Arzt und nicht in die Kategorie Augen zu und durch."
      },
      {
        "type": "p",
        "text": "Du willst sichergehen, dass dein Gewichtsverlust aus Fett besteht und nicht aus hart erarbeiteter Muskulatur? Genau dafür habe ich mein Coaching aufgebaut. Der erste Schritt ist ein kostenloses Erstgespräch von 30 bis 45 Minuten, in dem wir deinen Trainings- und Proteinstatus ehrlich durchgehen. Unverbindlich und ohne Verkaufsdruck."
      }
