        "type": "p",
        "text": "Die letzten beiden Punkte sind Forschungsfelder in Bewegung, keine Garantien. Ich nenne sie trotzdem, weil sie zeigen, in welche Richtung die Wissenschaft gerade denkt: Kreatin ist längst kein reines Kraftsportthema mehr."
