        "text": "Der letzte Punkt ärgert mich am meisten. Einige Hersteller verkaufen exakt dasselbe Pulver mit Blümchen-Etikett deutlich teurer. Der Wirkstoff kennt dein Geschlecht nicht. Ein Kilo solides Monohydrat kostet um die 20 bis 30 Euro und reicht bei täglicher Einnahme mehr als ein halbes Jahr."
