        "type": "p",
        "text": "Das „Cortisol-Face“: Ein rundes Gesicht kommt bei gesunden Menschen fast immer von Wassereinlagerungen, Schlafmangel, Alkohol oder schlicht Körperfett. Ein krankhaft erhöhter Cortisolspiegel, der das Gesicht verändert, heißt Cushing-Syndrom und gehört zum Arzt, nicht in eine Skincare-Routine."
